code.cpp:
class Solution {
public:
    int minDeletionSize(vector<string>& strs) {
        int n = strs.size();
        int m = strs[0].size();
        vector<bool> locked(n - 1, false);
        int answer = 0;
        for (int col = 0; col < m; col++) {
            bool canKeep = true;
            for (int i = 0; i < n - 1; i++) {
                if (!locked[i] && strs[i][col] > strs[i + 1][col]) {
                    canKeep = false;
                    break;
                }
            }
            if (canKeep) {
                for (int i = 0; i < n - 1; i++) {
                    if (!locked[i] && strs[i][col] < strs[i + 1][col]) {
                        locked[i] = true;
                    }
                }
            } else {
                answer++;
            }
        }
        return answer;
    }
};
